	static styles = [DsElement.styles, popoverStyles, styles]
	static properties = { label: {}, width: {} }

	/** The trigger's text and the menu's name. */
	label = ''
	/** The panel's width (a CSS length). */
	width = '224px'
	private wasOpen = false
	private pop = new PopoverController(this, {
		side: 'bottom',
		align: 'start',
		gap: 8,
		anchor: () => this.renderRoot.querySelector<HTMLElement>('button[role="menuitem"]'),
		panel: () => this.renderRoot.querySelector<HTMLElement>('.ds-pop'),
	})

	private get bar() {
		const b = this.closest(tagName('menubar')) as Menubar | null
		return b && typeof b.setActive === 'function' ? b : null
	}

	// A chosen row closes the menu, focus back on the trigger, unless the row keeps it open.
	private onSelect = (event: Event) => {
		const row = event.composedPath()[0] as Row
		if (row?.localName !== tagName('menubar-item')) return
		if (!row.keepOpen) this.pop.hide(true)
	}
	connectedCallback() {
		super.connectedCallback()
		this.addEventListener('select', this.onSelect)
	}
	disconnectedCallback() {
		super.disconnectedCallback()
		this.removeEventListener('select', this.onSelect)
	}

	private rows() {
		return [...this.querySelectorAll<Row>(tagName('menubar-item'))].filter((r) => !r.disabled)
	}
	/** Focuses the trigger (the bar's arrows). */
	focusTrigger() {
		this.renderRoot.querySelector<HTMLElement>('button[role="menuitem"]')?.focus()
	}
	/** Opens the menu, focusing its first or last row, or the panel. */
	async openMenu(focus: 'first' | 'last' | 'none' = 'first', keyboard = true) {
		await this.pop.show({ keyboard })
		await this.updateComplete
		if (focus === 'none') return this.renderRoot.querySelector<HTMLElement>('.ds-pop')?.focus({ preventScroll: true })
		const rows = this.rows()
		;(focus === 'last' ? rows.at(-1) : rows[0])?.focus()
	}

	private onClick = (event: MouseEvent) => {
		if (this.pop.open) return this.pop.hide(event.detail === 0, event.detail === 0)
		void this.openMenu(event.detail === 0 ? 'first' : 'none', event.detail === 0)
	}
	private onEnter = () => {
		const bar = this.bar
		if (bar?.active && bar.active !== this) void this.openMenu('none', true)
	}
	private onTriggerKey = (event: KeyboardEvent) => {
		if (event.key === 'ArrowRight' || event.key === 'ArrowLeft') {
			event.preventDefault()
			this.bar?.move(this, event.key === 'ArrowRight' ? 1 : -1, false)
		} else if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
			event.preventDefault()
			void this.openMenu(event.key === 'ArrowDown' ? 'first' : 'last')
		}
	}
	// The rows' keys, after Left and Right, which open the next menu.
	private onPanelKey = (event: KeyboardEvent) => {
		if (event.key === 'ArrowRight' || event.key === 'ArrowLeft') {
			event.preventDefault()
			this.pop.hide(false, true)
			this.bar?.move(this, event.key === 'ArrowRight' ? 1 : -1, true)
			return
		}
		onMenuRows(event, this.rows(), (refocus) => this.pop.hide(refocus))
	}
	protected updated(changed: PropertyValues<this>) {
		super.updated(changed)
		const bar = this.bar
		if (!bar) return
		if (this.pop.open !== this.wasOpen) {
			this.wasOpen = this.pop.open
			if (this.pop.open) bar.setActive(this)
			else if (bar.active === this) bar.setActive(null)
		}
		if (bar.active !== this && this.pop.open) this.pop.hide(false, true)
	}

	render() {
		const bar = this.bar
		const tabbable = !bar || bar.current() === this
		const panel = this.pop.rendered
			? html`<div data-ds="menubar-menu" popover="manual" class="ds-pop flex flex-col p-1 fade-y" role="menu" aria-label=${this.label} tabindex="-1" data-side=${this.pop.pos.side} ?data-instant=${this.pop.instant} ?data-placed=${this.pop.pos.placed} style=${this.pop.style(`width: ${this.width}`)} @keydown=${this.onPanelKey} @focusout=${this.pop.onFocusOut}><slot></slot></div>`
			: nothing
		return html`<button data-ds="menubar-menu" type="button" role="menuitem" aria-haspopup="menu" aria-expanded=${String(this.pop.open)} tabindex=${tabbable ? 0 : -1} class="inline-flex h-control-sm cursor-pointer items-center rounded-ds-sm px-3 type-ui-strong text-fg-soft -outline-offset-2 transition-[background-color,color] duration-160 ease-standard hover:not-aria-expanded:bg-action-ghost-hover hover:text-fg aria-expanded:bg-action-secondary aria-expanded:text-fg max-md:h-control-touch" @click=${this.onClick} @pointerenter=${this.onEnter} @focus=${() => this.bar?.setFocused(this)} @keydown=${this.onTriggerKey}>${this.label}</button>${panel}`
	}
}

define('menubar-menu', MenubarMenu)

import { html, LitElement, nothing } from 'lit'
import { ifDefined } from 'lit/directives/if-defined.js'
import { Check } from 'lucide'
import { DsElement, define } from '@/elements/lib/element'
import { icon } from '@/elements/lib/icon'
import styles from 'virtual:tw'

// MenubarItem.tsx as <spyglass-menubar-item>: one row of a menubar menu: 32px (44px on phones), DM Sans soft gray, the
// small corner; the row under the pointer or focus takes the #262626 fill and White type. Put a 16px Lucide icon first;
// `shortcut` shows muted at the end. `item-role` menuitemradio or menuitemcheckbox with `checked` makes a checked row.
// `danger` is a destructive row's red. Choosing it fires `select` and closes the menu, unless `keep-open`.

/**
 * @summary One row of a menubar menu.
 * @slot - The row: an icon and the label.
 * @fires select - The row was chosen.
 */
export class MenubarItem extends DsElement {
	static styles = [DsElement.styles, styles]
	static shadowRootOptions = { ...LitElement.shadowRootOptions, delegatesFocus: true }
	static properties = { shortcut: {}, danger: { type: Boolean }, disabled: { type: Boolean, reflect: true }, keepOpen: { type: Boolean, attribute: 'keep-open' }, checked: { type: Boolean }, itemRole: { attribute: 'item-role' } }

	/** A key or keys, shown muted at the end. */
	shortcut?: string
	/** A destructive row (red). */
	danger = false
	disabled = false
	/** Choosing it leaves the menu open. */
	keepOpen = false
	/** Checked, for a radio or checkbox row. */
	checked = false
	/** menuitem, menuitemradio or menuitemcheckbox. */
	itemRole: 'menuitem' | 'menuitemradio' | 'menuitemcheckbox' = 'menuitem'

	// The row under the pointer takes focus, so the pointer and the keys share one highlight.
	private onPointerMove = (event: PointerEvent) => {
		const el = event.currentTarget as HTMLElement
		if (!this.disabled && (this.renderRoot as ShadowRoot).activeElement !== el) el.focus({ preventScroll: true })
	}

	render() {
		const role = this.itemRole
		return html`<button data-ds="menubar-item" type="button" role=${role} aria-checked=${ifDefined(role === 'menuitem' ? undefined : String(this.checked))} ?disabled=${this.disabled} ?data-danger=${this.danger} class="flex h-control-sm w-full shrink-0 cursor-pointer items-center gap-3 rounded-ds-sm px-2 text-left type-ui text-fg-soft outline-none transition-[background-color,color] duration-160 ease-standard focus:bg-action-secondary focus:text-fg disabled:cursor-not-allowed disabled:text-fg-faint data-danger:text-fg-danger max-md:h-control-touch" @pointermove=${this.onPointerMove} @click=${() => this.emit('select')}><span class="flex min-w-0 flex-1 items-center gap-3"><slot></slot></span>${this.shortcut ? html`<span class="type-caption text-fg-muted">${this.shortcut}</span>` : nothing}${role !== 'menuitem' && this.checked ? icon(Check, 'check', { size: 16, strokeWidth: 1.5, class: 'shrink-0', attrs: { 'aria-hidden': 'true' } }) : nothing}</button>`
	}
}

define('menubar-item', MenubarItem)

